class Command(BaseCommand):
    help = 'Carga el arbol de emociones (114 emociones) de forma idempotente.'

    def handle(self, *args, **kwargs):
        self.stdout.write('Cargando emociones...')
        
        id_map = {}
        sorted_emociones = sorted(EMOCIONES_DATA, key=lambda x: (int(x['fields']['nivel']), x['pk']))

        creadas = 0
        actualizadas = 0

        for item in sorted_emociones:
            pk = item['pk']
            fields = item['fields']
            nombre = fields['nombre']
            nivel = fields['nivel']
            padre_pk = fields.get('padre')

            padre_obj = id_map.get(padre_pk) if padre_pk else None

            obj, created = Emocion.objects.get_or_create(
                nombre=nombre,
                defaults={
                    'nivel': nivel,
                    'padre': padre_obj
                }
            )

            if not created:
                obj.nivel = nivel
                obj.padre = padre_obj
                obj.save()
                actualizadas += 1
            else:
                creadas += 1

            id_map[pk] = obj

        self.stdout.write(self.style.SUCCESS(f'[OK] Emociones cargadas: {creadas} creadas, {actualizadas} actualizadas.'))
